import{et as e}from"./index-Bg_G4Hlo.js";var t={getStudents:(t=`all`)=>e.get(`/api/control/board/students?class_id=${t}`),autoNumber:(t,n,r)=>e.post(`/api/control/board/number`,{class_id:Number(t),field:n,start:Number(r)}),updateStudent:(t,n)=>e.put(`/api/control/board/students/${t}`,n),getCommittees:()=>e.get(`/api/control/board/committees`),saveCommittees:t=>e.post(`/api/control/board/committees`,{count:Number(t)}),saveAssignments:t=>e.put(`/api/control/board/committee-assignments`,{assignments:t})};export{t};